# Saving and Restoring DockView Configuration

DockView provides `toJSON()` and `fromJSON()` methods for serialization. Here's how to implement it:

```vue client/src/components/desktop/Desktop.vue
<script setup>
import { DockviewVue } from 'dockview-vue'
import Window from './Window.vue'
import AppWindow from '../windowManager/AppWindow.vue'
import LogViewer from '../LogViewer.vue'

import KnowledgeViewVue from "../../views/KnowledgeView.vue"
import KnowledgeSettingsVue from "../../views/KnowledgeSettings.vue"
import ProfileViewVue from "../../views/ProfileView.vue"
import CodxWelcomeView from "../../views/CodxWelcomeView.vue"
import ProjectSettingsVue from "../../views/ProjectSettings.vue"
import WikiViewVue from "../../views/WikiView.vue"
import DocsViewVue from "../../views/DocsView.vue"
import GlobalSettingsVue from "../../views/GlobalSettings.vue"
import KanbanContainerVue from "../kanban/KanbanContainer.vue"
import Files from "../apps/Files.vue"
import MetricsViewer from "../metrics/MetricsViewer.vue"
import AccountSettings from '../security/AccountSettings.vue'
import FileFinderVue from '../filebrowser/FileFinder.vue'
import ProjectOverview from "../project/ProjectOverview.vue"
import Wall from "../wall/Wall.vue"
import ChatView from '@/views/ChatView.vue'
import Tab from './Tab.vue'
</script>

<template>
  <dockview-vue
    class="dockview-theme-abyss w-full h-full"
    @ready="onReady"
    :components="registeredComponents"
  />
</template>

<script>
const STORAGE_KEY = 'dockview-layout'

export default {
  name: 'Desktop',
  components: {
    'dockview-vue': DockviewVue,
    'window': Window,
    'app-window': AppWindow,
    'log-viewer': LogViewer,
    'knowledge': KnowledgeViewVue,
    'knowledge_settings': KnowledgeSettingsVue,
    'profiles': ProfileViewVue,
    'home': CodxWelcomeView,
    'settings': ProjectSettingsVue,
    'wiki': WikiViewVue,
    'docs': DocsViewVue,
    'global-settings': GlobalSettingsVue,
    'tasks': KanbanContainerVue,
    'files': Files,
    'metrics': MetricsViewer,
    'account': AccountSettings,
    'file-finder': FileFinderVue,
    'projects': ProjectOverview,
    'activity': Wall,
    'chat': ChatView,
    'tab': Tab
  },
  props: {
    // Initial panels to render on mount
    panels: {
      type: Array,
      default: () => []
    },
    // localStorage key to persist layout
    storageKey: {
      type: String,
      default: STORAGE_KEY
    }
  },
  data() {
    return {
      dockviewApi: null,
      registeredComponents: {
        'window': Window,
        'app-window': AppWindow,
      }
    }
  },
  methods: {
    // Store dockview API, restore saved layout or add initial panels
    onReady(event) {
      this.dockviewApi = event.api
      const restored = this.restoreLayout()
      if (!restored) {
        this.panels.forEach(panel => this.addPanel(panel))
      }
    },

    // Add a new panel to the desktop
    addPanel({ id, title, component = 'window', position, params }) {
      if (!this.dockviewApi) return
      this.dockviewApi.addPanel({ id, title, component, position, params })
    },

    // Remove a panel by id
    removePanel(id) {
      if (!this.dockviewApi) return
      const panel = this.dockviewApi.getPanel(id)
      panel && this.dockviewApi.removePanel(panel)
    },

    // Register a new component so it can be used as a panel
    registerComponent(name, component) {
      this.registeredComponents = {
        ...this.registeredComponents,
        [name]: component
      }
    },

    // Serialize current layout to JSON and save to localStorage
    saveLayout() {
      if (!this.dockviewApi) return null
      const layout = this.dockviewApi.toJSON()
      localStorage.setItem(this.storageKey, JSON.stringify(layout))
      this.$emit('layout-saved', layout)
      return layout
    },

    // Load layout JSON from localStorage and restore it
    restoreLayout(layout = null) {
      if (!this.dockviewApi) return false
      try {
        const data = layout || JSON.parse(localStorage.getItem(this.storageKey))
        if (!data) return false
        this.dockviewApi.fromJSON(data)
        this.$emit('layout-restored', data)
        return true
      } catch (e) {
        console.warn('Failed to restore dockview layout:', e)
        return false
      }
    },

    // Clear saved layout from localStorage
    clearSavedLayout() {
      localStorage.removeItem(this.storageKey)
      this.$emit('layout-cleared')
    },

    // Get current layout as plain JSON object (without saving)
    getLayout() {
      return this.dockviewApi ? this.dockviewApi.toJSON() : null
    }
  },
  expose: [
    "addPanel",
    "removePanel",
    "registerComponent",
    "saveLayout",
    "restoreLayout",
    "clearSavedLayout",
    "getLayout"
  ]
}
</script>
```

## Usage Examples

### Auto-save on layout changes

```vue client/src/views/DesktopView.vue
<script setup>
import Desktop from '../components/desktop/Desktop.vue'
</script>

<template>
  <div class="w-full h-full">
    <Desktop
      ref="desktop"
      :panels="initialPanels"
      storage-key="my-app-layout"
      @layout-saved="onLayoutSaved"
      @layout-restored="onLayoutRestored"
    />

    <!-- Layout controls -->
    <div class="fixed bottom-4 right-4 flex gap-2">
      <button
        class="px-3 py-1 bg-blue-600 text-white rounded"
        @click="save"
      >
        Save Layout
      </button>
      <button
        class="px-3 py-1 bg-gray-600 text-white rounded"
        @click="reset"
      >
        Reset Layout
      </button>
    </div>
  </div>
</template>

<script>
export default {
  name: 'DesktopView',
  data() {
    return {
      initialPanels: [
        { id: 'home', title: 'Home', component: 'home' },
        { id: 'chat', title: 'Chat', component: 'chat' }
      ]
    }
  },
  methods: {
    save() {
      this.$refs.desktop.saveLayout()
    },

    reset() {
      this.$refs.desktop.clearSavedLayout()
      location.reload() // reload to restore defaults
    },

    onLayoutSaved(layout) {
      console.log('Layout saved:', layout)
    },

    onLayoutRestored(layout) {
      console.log('Layout restored:', layout)
    }
  }
}
</script>
```

## Key Methods Summary

| Method | Description |
|--------|-------------|
| `saveLayout()` | Calls `api.toJSON()` → saves to `localStorage` |
| `restoreLayout(layout?)` | Calls `api.fromJSON(data)` from storage or passed JSON |
| `getLayout()` | Returns current layout as JSON without saving |
| `clearSavedLayout()` | Removes saved layout from `localStorage` |

> ⚠️ **Important**: `fromJSON()` requires that all `component` names referenced in the saved layout are registered in `registeredComponents`. If a component is missing, the panel will fail to render.
